22	    /// </summary>
23	    /// <typeparam name="TEntity">The type of the entity.</typeparam>
24	    /// <seealso cref="Microsoft.AspNetCore.Mvc.Controller" />
25	    public abstract class EntityController<TEntity> : Controller
26	        where TEntity : class,IEntity
27	    {
28	        /// <summary>
29	        /// The repository for instances
30	        /// </summary>
31	        protected Repository<TEntity> repository;
32	        protected IHubContext<NotificationHub> hubContext;
33	        protected readonly ILogger<EntityController<TEntity>> _logger;
34	
35	        protected EntityController(IHubContext<NotificationHub> hubContext, ILogger<EntityController<TEntity>> logger)
36	        {
37	            this.hubContext = hubContext;
38	            _logger = logger;
39	        }
40	
41	        /// <summary>
42	        /// All instances.
43	        /// </summary>
44	        /// <param name="page">Current page.</param>
45	        /// <param name="rpp">Results per page.</param>
46	        /// <returns>rpp Instances for current page</returns>
47	        [HttpGet("[action]/{page:int}/{rpp:int}")]
48	        public virtual IEnumerable<Information> All(int page, int rpp)
49	        {
50	            _logger.LogInformation($"Executing All method, page={page}, rpp={rpp}");
51	            return repository.EntitiesInfo(rpp, (page - 1) * rpp);
52	        }
53	
54	        [HttpGet("[action]")]
55	        public virtual int Count()
56	        {
57	            _logger.LogInformation($"Executing Count method");
58	            return repository.EntitiesCount();
59	        }
60	
61	        /// <summary>
62	        /// Deletes the specified entity.
