115	        public override ProductInfosAndCount GetProductInformationsByProductFilter(ProductFilterInfo filter)
116	        {
117	            IQueryable<Product> products = context.Products;
118	
119	            if (filter.CategoryId.HasValue)
120	            {
121	                products = FilterByCategory(products, filter.CategoryId.Value);
122	            }
123	
124	            if (filter.IntProps != null && filter.IntProps.Any())
125	            {
126	                products = FilterByIntProps(products, filter.IntProps);
127	            }
128	
129	            if (filter.DecimalProps != null && filter.DecimalProps.Any())
130	            {
131	                products = FilterByDecimalProps(products, filter.DecimalProps);
132	            }
133	
134	            if (filter.StringProps != null && filter.StringProps.Any())
135	            {
136	                products = FilterByStringProps(products, filter.StringProps);
137	            }
138	
139	            if (!string.IsNullOrWhiteSpace(filter.SearchTerm))
140	            {
141	                products = FilterBySearch(products, filter.SearchTerm);
142	            }
143	
144	            if (filter.OrderBy == OrderBy.Property && !filter.SortingPropertyId.HasValue)
145	            {
146	                throw new ArgumentException("Sorting property must have value");
147	            }
148	
149	            products = OrderProducts(products, filter.OrderBy, filter.SortingPropertyId, filter.SortAscending);
150	
151	            return new ProductInfosAndCount
152	            {
153	                Count = products.Count(),
154	                Infos = products.Skip(filter.Skip).Take(filter.Quantity).Select(p => p.Info).ToList()
155	            };
156	        }
157	
158	        #region Filter private methods
159	
160	        private IQueryable<Product> OrderProducts(IQueryable<Product> products, OrderBy orderBy, Guid? sortingPropertyId, bool sortAscending)
161	        {
162	            IQueryable<Product> tmp;
163	
164	            switch (orderBy)
165	            {
166	                case OrderBy.Name:
167	                    tmp = products.OrderByDescending(p => p.Info.Name);
168	                    break;
169	                case OrderBy.Rating:
170	                    tmp = products.OrderByDescending(p => p.Info.Rating);
171	                    break;
172	                case OrderBy.Watches:
173	                    tmp = products.OrderByDescending(p => p.Info.Watches);
174	                    break;
175	                case OrderBy.Property:
176	                    return OrderByProperty(products, sortingPropertyId.Value, sortAscending);
177	                default:
178	                    throw new ArgumentException("Illegal sort type");
179	            }
180	
181	            return MaybeReverse(tmp, sortAscending);
182	        }
183	
184	        private IQueryable<T> MaybeReverse<T>(IQueryable<T> query, bool reverse)
185	        {
186	            return reverse ? query.AsEnumerable().Reverse().AsQueryable() : query;
187	        }
188	
189	        private IQueryable<Product> OrderByProperty(IQueryable<Product> products, Guid sortingPropertyId, bool sortAscending)
190	        {
191	            var property = context.Properties.First(p => p.Id == sortingPropertyId);
192	
193	            switch (property.Type)
194	            {
195	                case PropertyTypes.Decimal:
196	                    return OrderByPropertyCommon(products, sortingPropertyId, context.LinkProductPropertyDecimal, sortAscending);
197	                case PropertyTypes.Int:
198	                    return OrderByPropertyCommon(products, sortingPropertyId, context.LinkProductPropertyInt, sortAscending);
199	                case PropertyTypes.String:
200	                    return OrderByPropertyCommon(products, sortingPropertyId, context.LinkProductPropertyString, sortAscending);
201	                default:
202	                    throw new ArgumentException("Unknown property type");
203	            }
204	        }
205	
206	        private IQueryable<Product> OrderByPropertyCommon<T>(IEnumerable<Product> products, Guid sortingPropertyId, IQueryable<EAV<T>> eavs, bool sortAscending)
207	        {
208	            var tmp = products.GroupJoin(
209	                    eavs.Where(lpp => lpp.Property.Id == sortingPropertyId),
210	                    p => p.Id,
211	                    lpp => lpp.Product.Id,
212	                    (p, lpp) => new { Product = p, Links = lpp })
213	                .OrderByDescending(x => x.Links.Any());
214	
215	            if (sortAscending)
216	            {
217	                tmp = tmp.ThenBy(x =>
218	                {
219	                    var t = x.Links.FirstOrDefault();
220	                    return t == null ? default(T) : t.Value;
221	                });
222	            }
223	            else
224	            {
225	                tmp = tmp.ThenByDescending(x =>
226	                {
227	                    var t = x.Links.FirstOrDefault();
228	                    return t == null ? default(T) : t.Value;
229	                });
230	            }
231	
232	            return tmp.Select(x => x.Product).AsQueryable();
233	        }
234	
235	        private IQueryable<Product> FilterBySearch(IQueryable<Product> products, string searchTerm)
236	        {
237	            return products.Where(p => p.Info.Name.ToLower().Contains(searchTerm.ToLower()));
238	        }
239	
240	        private IQueryable<Product> FilterByCategory(IQueryable<Product> products, Guid categoryId)
241	        {
242	            var curCat = new CatWithSubs() { Cat = cats.FirstOrDefault(x => x.Id == categoryId) };
243	            var apropriateCats = GetRecursiveCats(ref curCat);
244	            apropriateCats.Add(curCat.Cat);
245	            return products.Where(p => apropriateCats.Contains(p.Category));
246	        }
247	
248	        private IQueryable<Product> FilterByDecimalProps(IQueryable<Product> products, IEnumerable<DecimalPropertyInfo> decimalProps)
249	        {
250	            var tmp = products.GroupJoin(
251	                    context.LinkProductPropertyDecimal,
252	                    p => p.Id,
253	                    lpp => lpp.Product.Id,
254	                    (p, lpp) => new { Product = p, Links = lpp });
255	
256	            foreach (var prop in decimalProps)
257	            {
258	                tmp = tmp.Where(group => group.Links.Any(lpp => lpp.Property.Id == prop.PropId && lpp.Value >= prop.Left && lpp.Value <= prop.Right));
259	            }
260	
261	            return tmp.Select(group => group.Product);
262	        }
263	
264	        private IQueryable<Product> FilterByStringProps(IQueryable<Product> products, IEnumerable<StringPropertyInfo> stringProps)
265	        {
266	            var tmp = products.GroupJoin(
267	                    context.LinkProductPropertyString,
268	                    p => p.Id,
269	                    lpp => lpp.Product.Id,
270	                    (p, lpp) => new { Product = p, Links = lpp });
271	
272	            foreach (var prop in stringProps)
273	            {
274	                tmp = tmp.Where(group => group.Links.Any(lpp => lpp.Property.Id == prop.PropId && lpp.Value.Contains(prop.Part)));
275	            }
276	
277	            return tmp.Select(group => group.Product);
278	        }
279	
280	        private IQueryable<Product> FilterByIntProps(IQueryable<Product> products, IEnumerable<IntPropertyInfo> intProps)
281	        {
282	            var tmp = products.GroupJoin(
283	                    context.LinkProductPropertyInt,
284	                    p => p.Id,
285	                    lpp => lpp.Product.Id,
286	                    (p, lpp) => new { Product = p, Links = lpp });
287	
288	            foreach (var prop in intProps)
289	            {
290	                tmp = tmp.Where(group => group.Links.Any(lpp => lpp.Property.Id == prop.PropId && lpp.Value >= prop.Left && lpp.Value <= prop.Right));
291	            }
292	
293	            return tmp.Select(group => group.Product);
294	        }
295	
296	        #endregion
297	
298	        public IEnumerable<Category> GetSubCategories(Guid id)
299	        {
300	            return Categories().Where(x => x.BaseCategory?.Id == id);
301	        }
302	
303	        private List<Category> GetRecursiveCats(ref CatWithSubs cur)
304	        {
305	            var result = new List<Category>();
306	            var subs = new List<CatWithSubs>();
307	            var curSubCats = GetSubCategories(cur.Cat.Id);
308	            if (curSubCats.Any())
309	            {
310	                foreach (var cat in curSubCats)
311	                {
312	                    result.Add(cat);
313	                    var tmp = new CatWithSubs() { Cat = cat };
314	                    result.AddRange(GetRecursiveCats(ref tmp));
315	                    var tmpClone = new CatWithSubs() { Cat = tmp.Cat, Subs = tmp.Subs };
316	                    subs.Add(tmpClone);
317	                }
318	            }
319	
320	            cur.Subs = subs;
321	            return result;
322	        }
323	    }
324	}
